mica."},{"code":"14401086","playlist_id":"PL-uRhZ_p-BM6vqy0uBwWkO9Hb7dTlwPow","ord":2,"confidence":"média","level":"superior (introdutório)","match":"Comércio internacional: vantagem comparativa, ganhos do comércio, tarifas e protecionismo (Marginal Revolution University)."},{"code":"14401088","playlist_id":"PLxI8Can9yAHePQrbm_Z5TZD278IlPyNUL","ord":1,"confidence":"média","level":"superior","match":"Projetos e métodos para a produção do conhecimento: tema, problema, metodologia."},{"code":"14401088","playlist_id":"PLnQHdlRVYl7J1Z5MVM03Myz32M_MorI_Y","ord":2,"confidence":"média","level":"superior","match":"Metodologia científica: projeto de pesquisa, leitura crítica, levantamento bibliográfico."}]
$fpl$::jsonb) AS x(code text,playlist_id text,ord integer,confidence text,level text,match text);

DO $pre$ BEGIN
 IF (SELECT count(*) FROM _u)<>32 OR (SELECT count(DISTINCT code) FROM _u)<>32
 OR (SELECT sum(ects) FROM _u WHERE option_group IS NULL)<>168 OR (SELECT count(*) FROM _u WHERE option_group IS NULL)<>28
 OR (SELECT count(*) FROM _u WHERE option_group='Opção I (G)')<>2 OR (SELECT count(*) FROM _u WHERE option_group='Opção II (G)')<>2
 OR EXISTS(SELECT 1 FROM _u WHERE option_group IS NOT NULL AND ects<>6)
 OR EXISTS(SELECT 1 FROM _u WHERE jsonb_array_length(placements)<>1 OR placements->0->>'specialization'<>'Tronco Comum'
     OR (placements->0->>'role'='mandatory')<>(option_group IS NULL))
 OR (SELECT count(*) FROM _p)<>46 OR (SELECT count(*) FROM _pl)<>47 OR EXISTS(SELECT 1 FROM _pl WHERE confidence NOT IN ('alta','média'))
 THEN RAISE EXCEPTION 'Unexpected Economia manifest counts or ECTS (expected 180 = 168 + 6 + 6)'; END IF;
 IF EXISTS(SELECT 1 FROM _p WHERE id !~ '^PL[A-Za-z0-9_-]{10,60}$' OR url<>'https://www.youtube.com/playlist?list='||id
 OR length(trim(title))<3 OR videos<4 OR language NOT IN('pt-PT','pt-BR','en'))
 OR EXISTS(SELECT 1 FROM _pl t LEFT JOIN _p p ON p.id=t.playlist_id LEFT JOIN _u u ON u.code=t.code WHERE p.id IS NULL OR u.code IS NULL)
 THEN RAISE EXCEPTION 'Invalid playlist metadata or link'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.courses WHERE (code='LECON' OR slug='economia' OR (external_source='ualg_official' AND external_id='1440'))
 AND id<>md5('facodi:ualg:1440:course:record')::uuid)
 THEN RAISE EXCEPTION 'Another course already uses LECON, economia or UAlg 1440; reconcile manually'; END IF;
 IF EXISTS(SELECT 1 FROM facodi.curricular_units cu JOIN _u u ON u.code=cu.code OR u.code=cu.slug
 WHERE cu.course_id<>md5('facodi:ualg:1440:course:record')::uuid)
 THEN RAISE EXCEPTION 'A UC code already belongs to another course; reconcile manually'; END IF;
END $pre$;

INSERT INTO facodi.learning_objects(id,object_type,title,slug,description,objectives,keywords,tags,language,status,published,source_type,source_url,source_id,metadata)
VALUES(md5('facodi:ualg:1440:course')::uuid,'course','Licenciatura em Economia','facodi-course-economia',
 'Licenciatura da Faculdade de Economia da Universidade do Algarve, com 180 ECTS em três anos. Microeconomia, macroeconomia, econometria e economia internacional, com formação complementar em gestão, contabilidade, finanças, métodos quantitativos e direito.','[]'::jsonb,ARRAY['Economia','Microeconomia','Macroeconomia','Econometria','Finanças'],ARRAY['Economia'],
 'pt','active',true,'import','https://www.ualg.pt/curso/1440','ualg:licenciatura:1440:course',
 jsonb_build_object('university_course_code','1440','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1440/plano',
 'source_quality','ualg_official_programme','curation_batch','facodi_ualg_1440_economia_20261118'))
ON CONFLICT DO NOTHING;

INSERT INTO facodi.courses(id,learning_object_id,code,external_source,external_id,slug,title,normalized_title,summary,description_html,
 degree_type,language,school,source_url,plan_url,status,published,metadata,institution,ects_total,duration_semesters)
VALUES(md5('facodi:ualg:1440:course:record')::uuid,md5('facodi:ualg:1440:course')::uuid,'LECON','ualg_official','1440','economia',
 'Licenciatura em Economia','Economia','Licenciatura da Faculdade de Economia da Universidade do Algarve, com 180 ECTS em três anos. Microeconomia, macroeconomia, econometria e economia internacional, com formação complementar em gestão, contabilidade, finanças, métodos quantitativos e direito.','<h2>Apresentação</h2><p>Estudar Economia é estudar o modo como as sociedades se organizam para produzir os bens e serviços necessários à satisfação das necessidades humanas e como os distribuem entre os seus membros. O curso oferece uma formação sólida em teoria económica e uma formação geral em áreas complementares como a gestão, os métodos quantitativos e o direito.</p><h2>Plano de estudos</h2><p>Seis semestres com cinco unidades curriculares de 6 ECTS em cada um: 28 obrigatórias e dois grupos de opção no 3.º ano, Opção I (G) e Opção II (G). Os dois primeiros anos dão as bases de economia, matemática, estatística, contabilidade e finanças; o 3.º ano aprofunda econometria, finanças públicas, economia monetária e financeira, economia internacional e história do pensamento económico.</p><h2>Na FACODI</h2><p>Cada unidade curricular tem playlists abertas do YouTube escolhidas a partir do programa da ficha oficial da UC.</p>',
 'Licenciatura','pt','Faculdade de Economia','https://www.ualg.pt/curso/1440','https://www.ualg.pt/curso/1440/plano','active',true,
 jsonb_build_object('official_course_id','1440','official_academic_year','2026/27','official_plan_url','https://www.ualg.pt/curso/1440/plano',
 'official_program_verified',true,'official_ects_total',180,'official_unit_count',32,'mandatory_unit_count',28,
 'curriculum_contains_elective_alternatives',true,'alternative_pathways_not_additive',true,
 'teaching_language','Português','source_quality','ualg_official_programme','curriculum_review_status','approved_official_plan','curation_batch','facodi_ualg_1440_economia_20261118'),
 'Universidade do Algarve',180,6)
ON CONFLICT DO NOTHING;

